"Pour tout ton carnet, voyages partagés compris : tes compagnons en profitent aussi. Sans engagement : à l’arrêt, tout reste visible 6 mois.":"आपकी पूरी नोटबुक के लिए, साझा यात्राएँ शामिल: आपके साथियों को भी फ़ायदा। कोई बंधन नहीं: बंद करने पर सब 6 महीने तक दिखता रहेगा।",
