"Ton carnet est presque plein":"आपकी नोटबुक लगभग भर गई है",
"{0} utilisés sur {1}.":"{1} में से {0} इस्तेमाल।",
"Une fois plein, tes nouvelles photos restent sur ton téléphone sans partir dans le cloud.":"भर जाने पर आपकी नई फ़ोटो क्लाउड में जाए बिना फ़ोन पर रहेंगी।",
"Voir ma place":"मेरी जगह देखें",
"☁️ Le cloud change : c’est maintenant tout ton carnet ou rien.\n\nTes voyages déjà en ligne restent en ligne. En mettant tout ton carnet dans le cloud, ils s’y rattachent et tu reçois ton code administrateur pour retrouver tout ton compte sur un autre appareil.\n\nOK = mettre tout mon carnet dans le cloud (chiffré).\nAnnuler = garder comme maintenant.":"☁️ क्लाउड बदल रहा है: अब पूरी नोटबुक या कुछ नहीं।\n\nजो यात्राएँ पहले से ऑनलाइन हैं, वे ऑनलाइन रहेंगी। पूरी नोटबुक क्लाउड में रखने पर वे उससे जुड़ जाएँगी और आपको एडमिन कोड मिलेगा, जिससे आप दूसरे डिवाइस पर पूरा खाता वापस पा सकें।\n\nठीक है = मेरी पूरी नोटबुक क्लाउड में रखें (एन्क्रिप्टेड)।\nरद्द करें = जैसा है वैसा रहने दें।",
"Pour inviter quelqu’un, ton carnet doit être dans le cloud (chiffré : personne d’autre ne peut le lire).\n\nLe voyage partagé s’y rattache et ses photos, celles de tes compagnons aussi, comptent dans ta place.\n\nOK = mettre mon carnet dans le cloud.\nAnnuler = envoyer plutôt un paquet chiffré.":"किसी को आमंत्रित करने के लिए आपकी नोटबुक क्लाउड में होनी चाहिए (एन्क्रिप्टेड: कोई और इसे नहीं पढ़ सकता)।\n\nसाझा यात्रा उससे जुड़ती है और उसकी फ़ोटो, आपके साथियों की भी, आपकी जगह में गिनी जाती हैं।\n\nठीक है = मेरी नोटबुक क्लाउड में रखें।\nरद्द करें = इसके बजाय एन्क्रिप्टेड पैकेज भेजें।",
"Ton carnet est dans le cloud. Ton code administrateur est dans ☁️ Cloud.":"आपकी नोटबुक क्लाउड में है। आपका एडमिन कोड ☁️ क्लाउड में है।",
"Tes voyages sont sauvegardés et te suivent sur tous tes appareils. Partage avec tes compagnons et tes abonnés, notifications.":"आपकी यात्राएँ सहेजी जाती हैं और आपके सभी डिवाइस पर साथ रहती हैं। साथियों और फ़ॉलोअर्स के साथ साझा करना, सूचनाएँ।",
"Rien sur nos serveurs et aucune limite de photos : tout reste sur ton téléphone ou ton ordinateur. Tu partages par paquets chiffrés que tu envoies toi-même. Pas d’abonnés ni de notifications entre amis, et pense à ta sauvegarde ZIP.":"हमारे सर्वर पर कुछ नहीं और फ़ोटो की कोई सीमा नहीं: सब आपके फ़ोन या कंप्यूटर पर रहता है। आप खुद भेजे गए एन्क्रिप्टेड पैकेज से साझा करते हैं। न फ़ॉलोअर्स, न दोस्तों के बीच सूचनाएँ, और अपना ZIP बैकअप याद रखें।",
"🗳️ Sondages du groupe dans le programme":"🗳️ कार्यक्रम में ग्रुप पोल",
