"Retirer l’accès de {0} ?\n\nSon appli ne pourra plus synchroniser ton carnet. Ce qu’il a déjà vu reste sur son téléphone.":"{0} की पहुँच हटाएँ?\n\nउनका ऐप अब आपकी नोटबुक सिंक नहीं कर पाएगा। जो उन्होंने पहले देखा है वह उनके फ़ोन पर रहेगा।",
"ce compagnon":"यह साथी",
"Accès retiré":"पहुँच हटा दी गई",
"Ajouter un de mes appareils":"मेरा कोई डिवाइस जोड़ें",
"Sur ton autre téléphone ou ton ordinateur (appli installée) : ☁️ Cloud → « Tu as déjà un code ? » → 📷 Scanner. Tout ton carnet arrive, avec tes voyages partagés et suivis.":"अपने दूसरे फ़ोन या कंप्यूटर पर (ऐप इंस्टॉल हो): ☁️ क्लाउड → “पहले से कोड है?” → 📷 स्कैन। आपकी पूरी नोटबुक आ जाएगी, साझा और फ़ॉलो की गई यात्राओं के साथ।",
"C’est ton code administrateur : il donne tous les droits. Ne le donne à personne. Pour un compagnon, crée plutôt un code compagnon.":"यह आपका एडमिन कोड है: यह सारे अधिकार देता है। इसे किसी को न दें। साथी के लिए इसके बजाय साथी कोड बनाएँ।",
"🔑 Mon code administrateur":"🔑 मेरा एडमिन कोड",
"Garde-le bien et ne le donne à personne : c’est lui qui ouvre TON compte sur un autre appareil (carnet, voyages partagés et suivis).":"इसे संभालकर रखें और किसी को न दें: यही दूसरे डिवाइस पर आपका खाता खोलता है (नोटबुक, साझा और फ़ॉलो की गई यात्राएँ)।",
"📱 Ajouter un de mes appareils (QR code)":"📱 मेरा कोई डिवाइस जोड़ें (QR कोड)",
"👥 Compagnons de tout mon carnet":"👥 मेरी पूरी नोटबुक के साथी",
"Un code compagnon ouvre ton carnet (voir, ajouter, modifier) sans tes droits d’administrateur : pas d’effacement, pas de gestion des accès.":"साथी कोड आपकी नोटबुक खोलता है (देखना, जोड़ना, बदलना) आपके एडमिन अधिकारों के बिना: मिटाना नहीं, पहुँच का प्रबंधन नहीं।",
"➕ Créer un code compagnon":"➕ साथी कोड बनाएँ",
"👥 Carnets où je suis compagnon":"👥 नोटबुक जिनमें मैं साथी हूँ",
"Quitter":"छोड़ें",
"Partager tout ton carnet ?\n\nLa personne recevra un code compagnon : elle verra TOUS tes voyages et pourra les compléter, sans tes droits d’administrateur (pas d’effacement, pas de gestion des accès). Tu pourras lui retirer l’accès. Pour ne partager qu’un voyage, utilise plutôt « Inviter » sur ce voyage.":"अपनी पूरी नोटबुक साझा करें?\n\nउस व्यक्ति को साथी कोड मिलेगा: वह आपकी सभी यात्राएँ देखेगा और उनमें जोड़ सकेगा, आपके एडमिन अधिकारों के बिना (मिटाना नहीं, पहुँच का प्रबंधन नहीं)। आप उसकी पहुँच हटा सकेंगे। सिर्फ़ एक यात्रा साझा करने के लिए उस यात्रा पर “आमंत्रित करें” इस्तेमाल करें।",
"Ils reçoivent un code compagnon et voient tous tes voyages, sans tes droits d’administrateur. Pour ta famille ou ton couple.":"उन्हें साथी कोड मिलता है और वे आपकी सभी यात्राएँ देखते हैं, आपके एडमिन अधिकारों के बिना। परिवार या जीवनसाथी के लिए।",
"🔑 Tu as déjà un code ?":"🔑 पहले से कोड है?",
"Ton code administrateur (celui de ton autre appareil : tout ton carnet arrive ici) ou un code compagnon reçu d’un proche.":"आपका एडमिन कोड (आपके दूसरे डिवाइस का: पूरी नोटबुक यहाँ आ जाएगी) या किसी करीबी से मिला साथी कोड।",
"Colle ton code administrateur ou ton code compagnon.":"अपना एडमिन कोड या साथी कोड पेस्ट करें।",
