"Ses commentaires et ❤️ sont masqués pour tous tes abonnés, elle est retirée de la liste et ne voit plus tes souvenirs : un nouveau lien est transmis automatiquement à tes autres abonnés, pas à elle.":"उनकी टिप्पणियाँ और ❤️ आपके सभी फ़ॉलोअर से छिपा दिए जाते हैं, उन्हें सूची से हटा दिया जाता है और वे आपकी यादें नहीं देख पाते: नया लिंक अपने आप आपके दूसरे फ़ॉलोअर को जाता है, उन्हें नहीं।",
