"OK = quitter quand même (elles restent dans le voyage partagé, pas chez toi). Annuler = réessayer plus tard.":"OK = फिर भी छोड़ें (वे साझा यात्रा में रहेंगी, आपके पास नहीं)। रद्द करें = बाद में फिर कोशिश करें।",
