"Pause de synchronisation : ce carnet s’est synchronisé très souvent. Reprise automatique dans quelques minutes.":"सिंक रुका हुआ है: यह जर्नल बहुत बार सिंक हुआ है। कुछ मिनटों में यह अपने आप फिर शुरू होगा।",
