"📤 Ils n’ont pas encore de voyage partagé avec toi : tu vas leur envoyer une invitation (QR code ou message).":"📤 आपके साथ उनकी अभी कोई साझा यात्रा नहीं है: आप उन्हें आमंत्रण भेजेंगे (QR कोड या संदेश)।",
