"👥 Voyage partagé avec {0}":"👥 यात्रा {0} के साथ शेयर हुई",
"📚 Tout mon carnet":"📚 मेरी पूरी डायरी",
"Partager tous tes voyages d’un coup : avec un compagnon (il complète tout), ou avec des abonnés en lecture seule (photos et récits, comme Polarsteps).":"अपनी सारी यात्राएँ एक साथ शेयर करें: किसी सहयात्री के साथ (वह सब कुछ भरता है) या सिर्फ़ पढ़ने वाले फ़ॉलोअर्स के साथ (फ़ोटो और कहानियाँ, Polarsteps की तरह)।",
"🔗 On t’a invité ?":"🔗 आपको आमंत्रण मिला?",
"Un code ou un lien reçu par message : colle-le ici pour rejoindre un voyage, un carnet, ou suivre un voyage.":"संदेश में मिला कोड या लिंक: किसी यात्रा या डायरी से जुड़ने या किसी यात्रा को फ़ॉलो करने के लिए उसे यहाँ पेस्ट करें।",
"🔗 Rejoindre avec un code":"🔗 कोड से जुड़ें",
"Colle le message, le lien ou le code reçu.":"मिला हुआ संदेश, लिंक या कोड पेस्ट करें।",
"XXXX-XXXX-XXXX ou le lien reçu":"XXXX-XXXX-XXXX या मिला हुआ लिंक",
"📋 Coller":"📋 पेस्ट करें",
"C’est le code de ton propre carnet : tu as déjà ces voyages.":"यह आपकी अपनी डायरी का कोड है: ये यात्राएँ आपके पास पहले से हैं।",
