"Un voyage importé deux fois, des souvenirs remplacés : l’appli retrouve les copies en trop et les photos qui ne servent plus à rien, sur ce téléphone et sur le serveur.":"दो बार इम्पोर्ट हुई यात्रा, बदली गई यादें: ऐप इस फ़ोन और सर्वर पर फ़ालतू कॉपियाँ और अब काम न आने वाली फ़ोटो ढूँढता है।",
