"On garde : créé le {0} · {1} souvenirs · {2} photos":"रखी जाएगी: {0} को बनी · {1} यादें · {2} फ़ोटो",
"À supprimer : créé le {0} · {1} souvenirs · {2} photos":"हटेगी: {0} को बनी · {1} यादें · {2} फ़ोटो",
"🗑 Supprimer les copies cochées":"🗑 चुनी हुई कॉपियाँ हटाएँ",
"Aucun voyage en double. 👍":"कोई डुप्लिकेट यात्रा नहीं। 👍",
