"Photos de souvenirs supprimés ou remplacés, restées sur ce téléphone ou sur le serveur. L’appli synchronise d’abord, puis ne retire que les photos qui ne sont dans aucune fiche. Sur le serveur, seules celles envoyées il y a plus de 3 jours partent (le temps que tous les téléphones aient synchronisé).":"हटाई या बदली गई यादों की फ़ोटो जो इस फ़ोन या सर्वर पर रह गईं। ऐप पहले सिंक करता है, फिर सिर्फ़ वे फ़ोटो हटाता है जो किसी कार्ड में नहीं हैं। सर्वर पर सिर्फ़ 3 दिन से पहले भेजी गई फ़ोटो हटती हैं (ताकि सभी फ़ोन सिंक हो जाएँ)।",
