"🔒 Stockage protégé : le téléphone ne fera pas de ménage dans tes voyages et tes photos.":"🔒 सुरक्षित स्टोरेज: फ़ोन आपकी यात्राएँ और फ़ोटो नहीं मिटाएगा।",
"⚠️ Stockage non protégé : si le téléphone manque de place, il peut effacer les données de l’appli.":"⚠️ असुरक्षित स्टोरेज: फ़ोन में जगह कम होने पर वह ऐप का डेटा मिटा सकता है।",
"Sur iPhone : ajoute Vezoria à l’écran d’accueil (Safari → Partager → « Sur l’écran d’accueil ») et ouvre-la de là. Garde aussi une 💾 sauvegarde complète de temps en temps.":"iPhone पर: Vezoria को होम स्क्रीन पर जोड़ें (Safari → शेयर करें → “होम स्क्रीन में जोड़ें”) और वहीं से खोलें। समय-समय पर 💾 पूरा बैकअप भी लें।",
"Installe Vezoria (Google Play ou « Installer l’appli ») et ouvre-la souvent : Android protège alors son stockage. Garde aussi une 💾 sauvegarde complète de temps en temps.":"Vezoria इंस्टॉल करें (Google Play या “ऐप इंस्टॉल करें”) और अक्सर खोलें: तब Android उसका स्टोरेज सुरक्षित रखता है। समय-समय पर 💾 पूरा बैकअप भी लें।",
"🧹 Libérer de la place":"🧹 जगह खाली करें",
"Pour les voyages terminés ({0}), les grandes photos déjà envoyées sur le serveur sont retirées de ce téléphone. Les vignettes restent : la grille et le film s’affichent toujours, et la grande photo revient du serveur, en version allégée, quand tu l’ouvres (il faut du réseau). Les photos pas encore envoyées ne sont jamais touchées.":"पूरी हो चुकी यात्राओं ({0}) की बड़ी फ़ोटो, जो पहले ही सर्वर पर भेजी जा चुकी हैं, इस फ़ोन से हटा दी जाती हैं। थंबनेल रहते हैं: ग्रिड और फ़िल्म दिखते रहते हैं, और खोलने पर बड़ी फ़ोटो हल्के रूप में सर्वर से लौट आती है (नेटवर्क चाहिए)। जो फ़ोटो अभी नहीं भेजी गईं, उन्हें कभी नहीं छुआ जाता।",
"Retirer de ce téléphone les grandes photos des voyages terminés déjà sur le serveur ? Les vignettes restent, et chaque grande photo revient quand tu l’ouvres.":"पूरी हो चुकी यात्राओं की सर्वर पर मौजूद बड़ी फ़ोटो इस फ़ोन से हटाएँ? थंबनेल रहेंगे, और हर बड़ी फ़ोटो खोलने पर लौट आएगी।",
