"Touche pour la montrer sur leur carte":"उनके नक्शे पर दिखाने के लिए दबाओ",
"La route du voyage":"यात्रा का रास्ता",
"Route visible des abonnés":"रास्ता फ़ॉलोअर्स को दिख रहा है",
"Route masquée aux abonnés":"रास्ता फ़ॉलोअर्स से छिपा है",
"Montrer ta route aux abonnés de ce voyage ?\n\nIls verront sur une carte le trajet enregistré par le suivi et ta dernière position (précision ≈ 100 m), avec l’heure.\nTu peux arrêter quand tu veux : la carte disparaît chez eux à la synchro suivante.\nTes compagnons choisissent chacun pour eux.":"इस यात्रा के फ़ॉलोअर्स को अपना रास्ता दिखाना है?\n\nवे नक्शे पर ट्रैकिंग से रिकॉर्ड हुआ रास्ता और तुम्हारी आख़िरी लोकेशन (≈ 100 मी. सटीकता) समय के साथ देखेंगे।\nतुम जब चाहो रोक सकते हो: अगले सिंक पर नक्शा उनके यहाँ से गायब हो जाएगा।\nहर साथी अपने लिए खुद तय करता है।",
"Publier « {0} » pour des abonnés ?\n\nIls verront uniquement les souvenirs : photos, titres, lieux et récits. Le programme, les réservations, le budget et les documents restent privés.\nUn souvenir marqué « privé » n’est jamais publié.\nIls voient les photos en vignettes (taille réduite).\nTa position n’est jamais montrée, sauf si chaque voyageur l’active lui-même dans le suivi du voyage.\nIls pourront mettre des ❤️ et des commentaires.":"फ़ॉलोअर्स के लिए “{0}” प्रकाशित करना है?\n\nवे सिर्फ़ यादें देखेंगे: फ़ोटो, शीर्षक, जगहें और कहानियाँ। कार्यक्रम, बुकिंग, बजट और दस्तावेज़ निजी रहेंगे।\n“निजी” चिह्नित याद कभी प्रकाशित नहीं होती।\nवे फ़ोटो थंबनेल (छोटे आकार) में देखते हैं।\nतुम्हारी लोकेशन कभी नहीं दिखाई जाती, जब तक हर यात्री खुद यात्रा ट्रैकिंग में उसे चालू न करे।\nवे ❤️ और टिप्पणियाँ दे सकेंगे।",
