"Facultatif : sauvegarde en ligne de tous tes voyages, pour les retrouver sur ton autre téléphone ou ta tablette avec le même code. Hors connexion, tout reste sur le téléphone et part dès que le réseau revient.":"वैकल्पिक: तुम्हारी सभी यात्राओं का ऑनलाइन बैकअप, ताकि उसी कोड से वे तुम्हें दूसरे फ़ोन या टैबलेट पर मिलें। ऑफ़लाइन होने पर सब फ़ोन पर रहता है और नेटवर्क लौटते ही भेज दिया जाता है।",
"Pour partager un seul voyage, inutile : dans le voyage, touche Partager. Seul ce voyage est alors stocké sur le serveur, tes autres voyages restent sur ton téléphone.":"सिर्फ़ एक यात्रा शेयर करने के लिए इसकी ज़रूरत नहीं: यात्रा में शेयर दबाओ। तब सिर्फ़ वही यात्रा सर्वर पर रखी जाती है, बाकी यात्राएँ तुम्हारे फ़ोन पर रहती हैं।",
