"Tu imagines ta prochaine aventure.":"तुम अपने अगले रोमांच की कल्पना करते हो।",
"Tu choisis une destination, une période et une ambiance qui te fait vibrer.":"तुम एक मंज़िल, एक समय और एक माहौल चुनते हो जो तुम्हें रोमांचित करे।",
"Ton voyage prend forme.":"तुम्हारी यात्रा आकार ले रही है।",
"Tu découvres des hébergements, des trajets, des activités, et tu ajustes l’itinéraire à ton image.":"तुम ठहरने की जगहें, सफ़र और गतिविधियाँ खोजते हो, और रास्ता अपने हिसाब से ढालते हो।",
"Tout est organisé.":"सब कुछ व्यवस्थित है।",
"Ton itinéraire est prêt : chaque jour, les lieux, les horaires, les réservations. Rien n’est laissé au hasard.":"तुम्हारा रास्ता तैयार है: हर दिन, जगहें, समय, बुकिंग। कुछ भी किस्मत पर नहीं छोड़ा गया।",
"Tu vis chaque instant.":"तुम हर पल जीते हो।",
"Tu découvres, tu profites, tu prends des photos. L’appli t’accompagne tout au long du chemin.":"तुम खोजते हो, आनंद लेते हो, फ़ोटो खींचते हो। ऐप पूरे रास्ते तुम्हारे साथ है।",
"Tu revis, tu partages, tu gardes.":"तुम फिर से जीते हो, शेयर करते हो, सँजोते हो।",
"Ton voyage devient un carnet vivant : photos, notes, émotions, et même les bons plans pour la prochaine fois.":"तुम्हारी यात्रा एक जीवंत डायरी बन जाती है: फ़ोटो, नोट्स, भावनाएँ, और अगली बार के लिए अच्छे सुझाव भी।",
"Tout commence par une idée…":"सब कुछ एक विचार से शुरू होता है…",
"Tu explores, tu choisis, tu construis.":"तुम खोजते हो, चुनते हो, बनाते हो।",
"Ton itinéraire, jour par jour.":"तुम्हारा रास्ता, दिन-ब-दिन।",
"Des souvenirs à chaque étape.":"हर पड़ाव पर यादें।",
"Parce que les plus beaux voyages se vivent deux fois.":"क्योंकि सबसे सुंदर यात्राएँ दो बार जी जाती हैं।",
"Chaque dépense raconte un bout du voyage.":"हर खर्च यात्रा का एक हिस्सा बताता है।",
"Une valise bien faite, un esprit léger.":"अच्छे से पैक किया बैग, हल्का मन।",
"Les petites idées font les grands voyages.":"छोटे विचार बड़ी यात्राएँ बनाते हैं।",
