"Partager « {0} » avec son propre code ?\n\nSeules les personnes qui ont ce code verront CE voyage (et pas tes autres voyages).\nLes compagnons déjà synchronisés par le code principal gardent ce qu’ils ont déjà, mais ne recevront plus les nouveautés de ce voyage.":"“{0}” को उसके अपने कोड से शेयर करना है?\n\nसिर्फ़ जिनके पास यह कोड है वही यह यात्रा देखेंगे (तुम्हारी बाकी यात्राएँ नहीं)।\nमुख्य कोड से पहले से सिंक साथियों के पास जो है वह रहेगा, पर इस यात्रा की नई चीज़ें उन्हें नहीं मिलेंगी।",
"⏳ première synchro…":"⏳ पहला सिंक…",
"Ce voyage a son propre code : seuls ceux qui l’ont le voient. Tes autres voyages restent privés.":"इस यात्रा का अपना कोड है: सिर्फ़ जिनके पास है वही देख सकते हैं। तुम्हारी बाकी यात्राएँ निजी रहती हैं।",
