"📤 Export prêt":"📤 एक्सपोर्ट तैयार",
"Ce fichier ne contient pas de carnet de voyage.":"इस फ़ाइल में कोई यात्रा डायरी नहीं है।",
"Le voyage 2027 existe déjà ici. Le remplacer par celui du fichier ?":"2027 की यात्रा यहाँ पहले से है। उसे फ़ाइल वाली से बदलें?",
"Fichier illisible : ce n’est pas un export JSON valide.":"फ़ाइल पढ़ी नहीं जा सकती: यह मान्य JSON एक्सपोर्ट नहीं है।",
"Le fichier contient aussi l’archive 2026. La restaurer ?":"फ़ाइल में 2026 का आर्काइव भी है। उसे बहाल करें?",
"Ce carnet n’est pas synchronisé : rien n’est stocké sur le serveur.":"यह डायरी सिंक नहीं है: सर्वर पर कुछ भी नहीं रखा गया।",
"Demander l’effacement de ce carnet sur le serveur ?\n\nToutes ses données en ligne seront supprimées, pour TOUS ses membres. Un e-mail va être préparé : il contient seulement l’identifiant chiffré du carnet, jamais son code.":"सर्वर से इस डायरी को मिटाने का अनुरोध करना है?\n\nइसका सारा ऑनलाइन डेटा सभी सदस्यों के लिए मिटा दिया जाएगा। एक ईमेल तैयार होगा: उसमें सिर्फ़ डायरी की एन्क्रिप्टेड आईडी होगी, कभी उसका कोड नहीं।",
"Les données restent sur le serveur partagé, tu pourras le rejoindre à nouveau avec le code.":"डेटा साझा सर्वर पर रहता है, तुम कोड से फिर जुड़ सकते हो।",
"Sans synchro, tout sera perdu : exporte avant !":"सिंक के बिना सब खो जाएगा: पहले एक्सपोर्ट करो!",
"Pour confirmer, écris EFFACER en majuscules :":"पुष्टि के लिए, बड़े अक्षरों में EFFACER लिखो:",
"Mot incorrect : rien n’a été effacé.":"ग़लत शब्द: कुछ नहीं मिटाया गया।",
"Méditerranée antique":"प्राचीन भूमध्य सागर",
"Rome → Malte → Athènes → Égypte":"रोम → माल्टा → एथेंस → मिस्र",
