": dans le calendrier d’un mois, le prix depuis les aéroports proches de chez toi.":": महीने के कैलेंडर में, तुम्हारे पास के एयरपोर्ट से कीमत।",
"3. Trouver le bon vol":"3. सही फ़्लाइट खोजें",
"Choisis ton aéroport de départ et tes dates (ou « N’importe où »). Touche une destination : le":"अपना प्रस्थान एयरपोर्ट और तारीख़ें चुनो (या “कहीं भी”)। कोई मंज़िल दबाओ:",
"calendrier couleur":"रंगीन कैलेंडर",
"montre chaque jour, du moins cher (vert) au plus cher (rouge). Un jour vert entouré = vol direct. Puis touche":"हर दिन दिखाता है, सबसे सस्ते (हरा) से सबसे महँगे (लाल) तक। घेरा हुआ हरा दिन = सीधी फ़्लाइट। फिर दबाओ",
"pour le prix réel du jour choisi.":"चुने गए दिन की असली कीमत के लिए।",
"4. Revenir au carnet":"4. डायरी पर वापस",
"Réserve chez la compagnie, puis dans le carnet :":"एयरलाइन से बुक करो, फिर डायरी में:",
"Résas → Trajets":"बुकिंग → सफ़र",
", ouvre le vol et remplis la compagnie, les horaires, le prix et le lien de réservation. Le budget et « qui doit quoi » se mettent à jour tout seuls.":", फ़्लाइट खोलो और एयरलाइन, समय, कीमत और बुकिंग लिंक भरो। बजट और “किसे क्या देना है” अपने आप अपडेट होते हैं।",
"💡 Le premium utilise des services payants à quota : garde-le pour tes vraies dates, et repasse en soft pour flâner.":"💡 प्रीमियम सीमित कोटा वाली पेड सेवाएँ इस्तेमाल करता है: इसे अपनी असली तारीख़ों के लिए रखो, और यूँ ही देखने के लिए सॉफ़्ट पर लौट आओ।",
