"Copie le texte de l’e-mail de réservation (vol, hôtel, train, bus…) et colle-le ici : l’appli repère la date, les horaires, la référence, la compagnie et le prix. Tu vérifies avant d’enregistrer. Rien n’est envoyé sur Internet.":"बुकिंग ईमेल (फ़्लाइट, होटल, ट्रेन, बस…) का टेक्स्ट कॉपी करके यहाँ पेस्ट करो: ऐप तारीख़, समय, संदर्भ, एयरलाइन और कीमत पहचानता है। सहेजने से पहले तुम जाँचते हो। इंटरनेट पर कुछ नहीं भेजा जाता।",
"🔍 Analyser":"🔍 विश्लेषण करें",
"Colle le texte complet de la confirmation.":"पुष्टि का पूरा टेक्स्ट पेस्ट करो।",
