"⏳ Un peu tôt : la fenêtre la plus souvent favorable est {0}–{1} semaines avant. Compare plusieurs dates sur les sites des compagnies.":"⏳ थोड़ा जल्दी है: सबसे अनुकूल समय अक्सर {0}–{1} हफ़्ते पहले होता है। एयरलाइन की वेबसाइटों पर कई तारीख़ें तुलना करो।",
"✅ Bonne période pour réserver ({0}–{1} semaines avant). Compare les prix sur les sites des compagnies.":"✅ बुक करने का अच्छा समय ({0}–{1} हफ़्ते पहले)। एयरलाइन की वेबसाइटों पर कीमतें तुलना करो।",
"⚠️ Départ proche : les prix montent souvent. Compare vite (dates voisines, aéroports proches).":"⚠️ प्रस्थान नज़दीक: कीमतें अक्सर बढ़ती हैं। जल्दी तुलना करो (आसपास की तारीख़ें, पास के एयरपोर्ट)।",
"· départ dans {0} semaine(s)":"· {0} हफ़्ते में प्रस्थान",
"par personne pour les trajets du voyage · repère : un aller-retour Paris–New York ≈ 1 t ; un Français émet ≈ 9 t par an":"यात्रा के सफ़रों के लिए प्रति व्यक्ति · संदर्भ: पेरिस–न्यूयॉर्क आना-जाना ≈ 1 टन; एक फ़्रांसीसी साल में ≈ 9 टन उत्सर्जित करता है",
"Ordres de grandeur (distance à vol d’oiseau corrigée × facteurs moyens type ADEME), pas un calcul certifié. Conseils de réservation = tendances générales, pas une prédiction de prix.":"मोटे अनुमान (सुधारी गई सीधी दूरी × ADEME जैसे औसत कारक), प्रमाणित गणना नहीं। बुकिंग सुझाव = सामान्य रुझान, कीमत की भविष्यवाणी नहीं।",
"📊 Mes stats de voyage":"📊 मेरी यात्रा के आँकड़े",
"📡 Je compte…":"📡 गिन रहे हैं…",
"Les pays apparaissent une fois les voyages commencés (ou avec « 📍 Je suis ici »).":"यात्राएँ शुरू होने पर देश दिखते हैं (या “📍 मैं यहाँ हूँ” से)।",
"km entre étapes":"पड़ावों के बीच किमी",
"pays visités":"घूमे हुए देश",
"steps 📍":"📍 क़दम",
"Pays comptés pour les voyages commencés, d’après les villes des hébergements et tes « Je suis ici ». Distances à vol d’oiseau entre étapes.":"शुरू हो चुकी यात्राओं के देश गिने जाते हैं, ठहरने की जगहों के शहरों और तुम्हारे “मैं यहाँ हूँ” के आधार पर। पड़ावों के बीच सीधी दूरियाँ।",
"🗺️ Préparation de l’export…":"🗺️ एक्सपोर्ट तैयार हो रहा है…",
