"Je suis ici":"मैं यहाँ हूँ",
"Rien à exporter : ajoute des hébergements avec leur ville ou des lieux à voir.":"एक्सपोर्ट करने को कुछ नहीं: शहर के साथ ठहरने की जगहें या देखने की जगहें जोड़ो।",
"Ajoute d’abord les hébergements (une ville par étape).":"पहले ठहरने की जगहें जोड़ो (हर पड़ाव पर एक शहर)।",
"Pour chaque étape, l’appli choisit les lieux les plus connus (Wikipédia, OpenStreetMap) et les répartit sur les jours, sans toucher à ce que tu as déjà prévu. Tu ajustes ensuite dans « Organiser l’étape ».":"हर पड़ाव के लिए, ऐप सबसे मशहूर जगहें चुनता है (Wikipedia, OpenStreetMap) और उन्हें दिनों में बाँटता है, जो पहले से तय है उसे छुए बिना। फिर “पड़ाव व्यवस्थित करें” में बदलाव करो।",
