"🪄 {0} lieux répartis sur tes journées libres.\nPour chaque jour : « Itinéraire » optimise l’ordre de visite et trace le parcours à pied.":"🪄 {0} जगहें तुम्हारे खाली दिनों में बाँटी गईं।\nहर दिन के लिए: “रास्ता” घूमने का क्रम अनुकूलित करता है और पैदल रास्ता बनाता है।",
