"Activer le suivi du voyage ?\n\n• Ta position est enregistrée environ tous les 300 m, seulement quand l’appli est ouverte (une appli web ne peut pas suivre en arrière-plan, téléphone en poche).\n• Un point est aussi ajouté à chaque ouverture de l’appli.\n• La route est partagée uniquement avec les personnes de CE voyage.\n• Tu peux l’arrêter à tout moment.":"यात्रा ट्रैकिंग चालू करनी है?\n\n• तुम्हारी लोकेशन लगभग हर 300 मी. पर दर्ज होती है, सिर्फ़ जब ऐप खुला हो (वेब ऐप बैकग्राउंड में, फ़ोन जेब में होने पर ट्रैक नहीं कर सकता)।\n• हर बार ऐप खोलने पर भी एक पॉइंट जुड़ता है।\n• रास्ता सिर्फ़ इसी यात्रा के लोगों के साथ साझा होता है।\n• तुम इसे कभी भी बंद कर सकते हो।",
"🛰️ Suivi activé":"🛰️ ट्रैकिंग चालू",
