"Sur iPhone, les notifications marchent quand Vezoria est ajoutée à l’écran d’accueil (Partager → « Sur l’écran d’accueil »), avec iOS 16.4 ou plus récent.":"iPhone पर नोटिफ़िकेशन तब काम करते हैं जब Vezoria होम स्क्रीन पर जोड़ा गया हो (शेयर → “होम स्क्रीन में जोड़ें”), iOS 16.4 या नए के साथ।",
"Ce navigateur ne sait pas recevoir de notifications.":"यह ब्राउज़र नोटिफ़िकेशन नहीं पा सकता।",
"Notifications refusées. Pour les autoriser : réglages du téléphone → Notifications → Vezoria.":"नोटिफ़िकेशन मना कर दिए गए। अनुमति देने के लिए: फ़ोन की सेटिंग्स → नोटिफ़िकेशन → Vezoria।",
