"Notifications":"नोटिफ़िकेशन",
"Les notifications sont bloquées pour Vezoria dans les réglages du téléphone. Autorise-les, puis reviens ici.":"फ़ोन की सेटिंग्स में Vezoria के नोटिफ़िकेशन ब्लॉक हैं। उन्हें अनुमति दो, फिर यहाँ लौटो।",
"Recevoir des notifications":"नोटिफ़िकेशन पाओ",
"Choisis ce qui t’intéresse :":"चुनो कि तुम्हें क्या चाहिए:",
"Ne pas déranger la nuit (22 h – 8 h)":"रात में परेशान न करें (रात 10 – सुबह 8)",
"M’envoyer une notification d’essai":"मुझे एक टेस्ट नोटिफ़िकेशन भेजो",
"Le contenu des notifications est chiffré : le serveur ne peut pas le lire. Tes compagnons choisissent les leurs.":"नोटिफ़िकेशन की सामग्री एन्क्रिप्टेड है: सर्वर उसे नहीं पढ़ सकता। तुम्हारे साथी अपने नोटिफ़िकेशन ख़ुद चुनते हैं।",
"Le contenu des notifications est chiffré : le serveur ne peut pas le lire. Tes compagnons choisissent les leurs. Pour être prévenu des ajouts de tes compagnons, partage d’abord un voyage.":"नोटिफ़िकेशन की सामग्री एन्क्रिप्टेड है: सर्वर उसे नहीं पढ़ सकता। तुम्हारे साथी अपने नोटिफ़िकेशन ख़ुद चुनते हैं। साथियों के जोड़े गए की ख़बर पाने के लिए पहले एक यात्रा शेयर करो।",
"Mode trajet":"सफ़र मोड",
