"Ce téléphone ne peut pas garder l’écran allumé : désactive la mise en veille automatique le temps du trajet.":"यह फ़ोन स्क्रीन चालू नहीं रख सकता: सफ़र के दौरान ऑटो-लॉक बंद कर दो।",
