"Rues, lieux à voir, hôtels et ta position sur une carte zoomable, même sans réseau ni données à l’étranger. À télécharger en Wi-Fi avant de partir.":"गलियाँ, देखने की जगहें, होटल और तुम्हारी लोकेशन ज़ूम होने वाले नक्शे पर, विदेश में बिना नेटवर्क या डेटा के भी। निकलने से पहले Wi-Fi पर डाउनलोड करो।",
"Recherche des étapes…":"पड़ाव खोजे जा रहे हैं…",
"Rues, lieux à voir, hôtels et ta position, même sans réseau ni données à l’étranger. À télécharger en Wi-Fi avant le départ.":"गलियाँ, देखने की जगहें, होटल और तुम्हारी लोकेशन, विदेश में बिना नेटवर्क या डेटा के भी। निकलने से पहले Wi-Fi पर डाउनलोड करो।",
