"Temples d’Angkor sur 3 jours, à vélo ou en tuk-tuk, poivre de Kampot.":"3 दिनों में अंगकोर के मंदिर, साइकिल या टुक-टुक से, काम्पोट की काली मिर्च।",
"Procession des moines à Luang Prabang, cascades de Kuang Si, 4000 îles du Mékong.":"लुआंग प्रबांग में भिक्षुओं की शोभायात्रा, कुआंग सी झरने, मेकांग के 4000 द्वीप।",
"Côté Andaman de décembre à avril, kayak dans les mangroves, Railay en long-tail.":"दिसंबर से अप्रैल अंडमान की ओर, मैंग्रोव में कयाकिंग, लॉन्ग-टेल नाव से रैले।",
"Temples de Chiang Mai, sanctuaire d’éléphants éthique, temple blanc de Chiang Rai.":"चियांग माई के मंदिर, नैतिक हाथी अभयारण्य, चियांग राय का सफ़ेद मंदिर।",
"Tortues autour des Gili, ascension du Rinjani, plages désertes du sud de Lombok.":"गिली के आसपास कछुए, रिंजानी की चढ़ाई, दक्षिणी लोम्बोक के सूने तट।",
