"Palais de Séoul en hanbok, temples de Gyeongju, marché aux poissons de Busan.":"हानबोक पहनकर सियोल के महल, ग्योंगजू के मंदिर, बुसान का मछली बाज़ार।",
"Marchés de nuit de Taipei, gorges de Taroko, lac du Soleil et de la Lune.":"ताइपे के रात्रि बाज़ार, तारोको घाटी, सूर्य-चंद्र झील।",
"Grande Muraille à Mutianyu, armée de terre cuite de Xi’an, train rapide entre les villes.":"मुतियान्यू में चीन की महान दीवार, शीआन की टेराकोटा सेना, शहरों के बीच तेज़ ट्रेन।",
"Victoria Peak, ferry Star, randonnée Dragon’s Back, dim sum le matin.":"विक्टोरिया पीक, स्टार फ़ेरी, ड्रैगन्स बैक ट्रेक, सुबह डिम सम।",
"Poudreuse et festival de la neige de Sapporo en février, lavande de Furano en juillet, plages d’Okinawa.":"फ़रवरी में पाउडर बर्फ़ और सापोरो हिम उत्सव, जुलाई में फ़ुरानो का लैवेंडर, ओकिनावा के तट।",
"Nuits en yourte chez l’habitant, festival du Naadam en juillet, dunes de Khongoryn Els.":"स्थानीय परिवारों के साथ यर्ट में रातें, जुलाई में नादम उत्सव, खोंगोरिन एल्स के टीले।",
"Opéra de Sydney et plages de Bondi, Grande Barrière de corail depuis Cairns, forêt de Daintree.":"सिडनी ओपेरा हाउस और बोंडी के तट, केर्न्स से ग्रेट बैरियर रीफ़, डेनट्री वर्षावन।",
"Van ou voiture, Milford Sound, randonnée du Tongariro, réserver les Great Walks.":"कैंपरवैन या कार, मिलफ़र्ड साउंड, टोंगारिरो क्रॉसिंग, ग्रेट वॉक्स बुक करें।",
"Art déco de South Beach, route des Keys, Everglades en hydroglisseur, parcs d’Orlando.":"साउथ बीच का आर्ट डेको, कीज़ का रास्ता, एवरग्लेड्स में एयरबोट, ऑरलैंडो के पार्क।",
"Highway 1 par Big Sur, Yosemite au printemps pour les cascades, Golden Gate à vélo.":"बिग सुर से होकर हाईवे 1, झरनों के लिए वसंत में योसेमिटी, साइकिल से गोल्डन गेट।",
"Route de Hana à Maui, lever du soleil au Haleakalā, volcans de Big Island.":"माउई में हाना की सड़क, हालेआकाला पर सूर्योदय, बिग आइलैंड के ज्वालामुखी।",
"Jazz sur Frenchmen Street, bayous en bateau, cuisine cajun et créole.":"फ़्रेंचमेन स्ट्रीट पर जैज़, नाव से बायू, काजुन और क्रियोल व्यंजन।",
"Lacs Louise et Moraine tôt le matin (navettes), Icefields Parkway, ours et wapitis.":"सुबह-सुबह लुईस और मोरेन झीलें (शटल), आइसफ़ील्ड्स पार्कवे, भालू और एल्क।",
"Stanley Park à vélo, baleines et ours depuis Tofino, ferry vers l’île.":"साइकिल से स्टैनली पार्क, टोफ़िनो से व्हेल और भालू, द्वीप की फ़ेरी।",
"Teotihuacán au lever du soleil, musée d’anthropologie, mole et mezcal à Oaxaca, Fête des morts début novembre.":"सूर्योदय पर तेओतिहुआकान, मानवविज्ञान संग्रहालय, ओआहाका में मोले और मेज़काल, नवंबर की शुरुआत में मृतकों का दिन।",
"Casas particulares, vieille Havane en voiture américaine, vallée de Viñales à cheval. Prévoir des espèces.":"कासास पार्तिकुलारेस, पुरानी अमेरिकी कार में पुराना हवाना, घोड़े पर विन्यालेस घाटी। नक़द साथ रखें।",
"Baleines à bosse de Samaná en février, plage de Playa Rincón, île Saona.":"फ़रवरी में सामाना की हंपबैक व्हेल, प्लाया रिंकॉन तट, साओना द्वीप।",
"Antigua et ses volcans, villages du lac Atitlán, cité maya de Tikal à l’aube.":"अंतिगुआ और उसके ज्वालामुखी, आतितलान झील के गाँव, भोर में माया नगर तिकाल।",
"Écluses de Miraflores, café de Boquete, îles de San Blas chez les Guna.":"मिराफ़्लोरेस लॉक्स, बोकेते की कॉफ़ी, गूना लोगों के साथ सान ब्लास द्वीप।",
"Machu Picchu à réserver des mois à l’avance, s’acclimater à Cuzco avant le trek, lac Titicaca.":"माचू पिच्चू महीनों पहले बुक करें, ट्रेक से पहले कुस्को में अनुकूलन, टिटिकाका झील।",
"Salar d’Uyuni en 4x4 sur 3 jours, téléphériques de La Paz, attention à l’altitude.":"3 दिनों में 4x4 से उयूनी नमक का मैदान, ला पाज़ की केबल कारें, ऊँचाई से सावधान।",
"Désert d’Atacama et ses lagunes, Torres del Paine (réserver les refuges), murs peints de Valparaíso.":"अटाकामा रेगिस्तान और उसके लैगून, तोर्रेस देल पाइने (आश्रय बुक करें), वालपराइसो के भित्तिचित्र।",
"Tango à San Telmo, chutes d’Iguazú des deux côtés, Quebrada de Humahuaca, vignobles de Mendoza.":"सान तेल्मो में टैंगो, दोनों ओर से इगुआसू झरने, केब्रादा दे उमाउआका, मेंदोसा के बाग।",
"Pain de Sucre au coucher du soleil, Paraty et ses îles, carnaval en février.":"सूर्यास्त पर शुगरलोफ़ पर्वत, पाराती और उसके द्वीप, फ़रवरी में कार्निवल।",
"Vallée de Cocora et ses palmiers de cire, Comuna 13 à Medellín, remparts de Carthagène.":"कोकोरा घाटी और मोम-ताड़, मेडेयिन में कोमुना 13, कार्ताहेना की प्राचीर।",
