"Lémuriens d’Andasibe, allée des Baobabs au coucher du soleil, plages de Nosy Be.":"अंदासिबे के लीमर, सूर्यास्त पर बाओबाब मार्ग, नोसी बे के तट।",
"Lagon du Morne, terre des sept couleurs de Chamarel, dauphins de Tamarin tôt le matin.":"ल मोर्न लैगून, शामारेल की सात रंगों वाली मिट्टी, सुबह-सुबह तामारिन की डॉल्फ़िन।",
"Anse Source d’Argent à La Digue, vallée de Mai à Praslin, guesthouses plutôt que resorts.":"ला दीग पर आंस सूर्स दार्जां, प्रास्लिन पर वाले दे मे, रिज़ॉर्ट की जगह गेस्टहाउस।",
